### 6.3 — `src/lib/queue.ts` (BullMQ Queue)

```ts
import { Queue } from "bullmq";
import { redis } from "./redis";

export interface SubmissionJobData {
  submissionId: string;   // DB record ID — worker fetches details from here
  problemId: string;
  language: "javascript" | "python";
  code: string;
  userId: string;
}

export const submissionQueue = new Queue<SubmissionJobData>("submission", {
  connection: redis,
  defaultJobOptions: {
    attempts: 3,                // Retry up to 3 times on failure
    backoff: {
      type: "exponential",
      delay: 1000,              // 1s, 2s, 4s
    },
    removeOnComplete: {
      age: 3600,                // Clean completed jobs after 1 hour
    },
    removeOnFail: {
      age: 86400,               // Keep failed jobs for 24 hours (debugging)
    },
  },
});
```

