### 6.4 — Refactored `SubmissionService`

The key change: **`submitSolution()` no longer calls Piston directly.** It creates a `PENDING` DB record and enqueues a BullMQ job.

```ts
// src/services/submission.service.ts

import { submissionQueue, SubmissionJobData } from "@/lib/queue";
import { ISubmissionRepo } from "@/repositories/submission/ISubmissionRepo";
import { _ProblemService } from "./problem.service";

export class _SubmissionService {
  private readonly submissionRepo: ISubmissionRepo;
  private readonly problemService: _ProblemService;

  constructor(submissionRepo: ISubmissionRepo, problemService: _ProblemService) {
    this.submissionRepo = submissionRepo;
    this.problemService = problemService;
  }

  /**
   * Creates a PENDING submission record and enqueues the job.
   * Returns immediately — no Piston call here.
   */
  async submitSolution(
    problemId: string,
    language: "javascript" | "python",
    code: string,
    userId: string,
  ) {
    // Validate problem exists before queueing
    const problem = await this.problemService.findByIdAllTests(problemId);
    if (!problem) throw new Error("Problem not found");

    // 1. Create submission in DB with status PENDING
    const submission = await this.submissionRepo.createSubmission({
      userId,
      problemId: problem.id,
      language,
      code,
      passed: false,       // false until worker confirms all tests pass
      passedAt: null,
      status: "PENDING",
    });

    // 2. Enqueue job for the worker
    const jobData: SubmissionJobData = {
      submissionId: submission.id,
      problemId: problem.id,
      language,
      code,
      userId,
    };

    await submissionQueue.add("execute", jobData, {
      jobId: submission.id,  // Deduplicate by submission ID
    });

    // 3. Return immediately
    return {
      submissionId: submission.id,
      status: "PENDING",
    };
  }

  /**
   * Fetches current status + results for the polling endpoint.
   */
  async getSubmissionStatus(submissionId: string, userId: string) {
    return this.submissionRepo.findById(submissionId, userId);
  }
}
```

