### 6.5 — `src/worker/submission.worker.ts` (Standalone Worker)

This is a **separate Node.js process** — not part of Next.js. It's started independently.

```ts
// src/worker/submission.worker.ts

import { Worker, Job } from "bullmq";
import IORedis from "ioredis";
import { SubmissionJobData } from "@/lib/queue";
import { executeCode } from "@/lib/piston";
import { randomMessage } from "@/lib/messages";
import { prisma } from "@/lib/prisma";

const redis = new IORedis(process.env.REDIS_URL || "redis://localhost:6379", {
  maxRetriesPerRequest: null,
});

const worker = new Worker<SubmissionJobData>(
  "submission",
  async (job: Job<SubmissionJobData>) => {
    const { submissionId, problemId, language, code } = job.data;

    console.log(`[Worker] Processing submission ${submissionId}...`);

    // ── Step 1: Mark as RUNNING ──
    await prisma.submission.update({
      where: { id: submissionId },
      data: { status: "RUNNING" },
    });

    // ── Step 2: Fetch test cases ──
    const problem = await prisma.problem.findUnique({
      where: { id: problemId },
      include: { testCases: true },
    });

    if (!problem) throw new Error(`Problem ${problemId} not found`);

    const fnName = language === "javascript" ? problem.fnNameJs : problem.fnNamePy;
    const testCases = problem.testCases.map((tc) => ({
      input: tc.input as unknown[],
      expected: tc.expected,
    }));

    // ── Step 3: Execute via Piston ──
    const { results } = await executeCode(language, code, fnName, testCases);
    const passedCount = results.filter((r) => r.passed).length;
    const allPassed = passedCount === results.length;

    // ── Step 4: Mark as COMPLETED ──
    const message = randomMessage(allPassed);

    await prisma.submission.update({
      where: { id: submissionId },
      data: {
        status: "COMPLETED",
        passed: allPassed,
        passedAt: allPassed ? new Date() : null,
        results: results as any,     // Store full test results as JSON
        message,
      },
    });

    console.log(`[Worker] Submission ${submissionId} → ${allPassed ? "PASSED ✅" : "FAILED ❌"}`);

    return { passed: allPassed, passedCount, totalCount: results.length };
  },
  {
    connection: redis,
    concurrency: 3,   // Process up to 3 submissions in parallel
  },
);

// ── Error Handling ──
worker.on("failed", async (job, err) => {
  if (!job) return;
  console.error(`[Worker] Job ${job.id} failed:`, err.message);

  // Mark as FAILED in DB after all retries exhausted
  if (job.attemptsMade >= (job.opts.attempts ?? 3)) {
    await prisma.submission.update({
      where: { id: job.data.submissionId },
      data: {
        status: "FAILED",
        error: err.message || "Unknown execution error",
      },
    });
  }
});

worker.on("completed", (job) => {
  console.log(`[Worker] Job ${job?.id} completed successfully`);
});

worker.on("ready", () => {
  console.log("[Worker] 🚀 Submission worker is ready and listening...");
});
```

**Start the worker:**

```bash
npx tsx src/worker/submission.worker.ts
```

Add to `package.json` scripts:

```json
{
  "scripts": {
    "worker": "tsx src/worker/submission.worker.ts",
    "worker:dev": "tsx watch src/worker/submission.worker.ts"
  }
}
```

