### 6.6 — Polling API: `GET /api/submit/status`

The frontend polls this endpoint to check submission progress.

```ts
// src/app/api/submit/status/route.ts

import { NextRequest, NextResponse } from "next/server";
import { requireAuth } from "@/lib/auth-guard";
import { SubmissionService } from "@/container";

export async function GET(req: NextRequest) {
  const { session, error } = await requireAuth();
  if (error) return error;

  const submissionId = req.nextUrl.searchParams.get("id");
  if (!submissionId) {
    return NextResponse.json({ error: "Missing submission ID" }, { status: 400 });
  }

  const submission = await SubmissionService.getSubmissionStatus(
    submissionId,
    session.user.id,
  );

  if (!submission) {
    return NextResponse.json({ error: "Submission not found" }, { status: 404 });
  }

  return NextResponse.json({
    status: submission.status,
    passed: submission.passed,
    results: submission.results,
    message: submission.message,
    error: submission.error,
  });
}
```

