### 6.8 — Refactored `/api/submit` Route

```ts
// src/app/api/submit/route.ts

export async function POST(req: NextRequest) {
  try {
    const { session, error } = await requireAuth();
    if (error) return error;

    const body = await req.json();
    const parsed = submitSchema.safeParse(body);
    if (!parsed.success) {
      return NextResponse.json({ error: parsed.error.flatten().fieldErrors }, { status: 400 });
    }

    const { code, language, problemId } = parsed.data;

    // Returns immediately with { submissionId, status: "PENDING" }
    const result = await SubmissionService.submitSolution(
      problemId, language, code, session.user.id,
    );

    return NextResponse.json(result, { status: 202 }); // 202 Accepted
  } catch (err) {
    console.error("Submit error:", err);
    return NextResponse.json({ error: "Submission failed" }, { status: 500 });
  }
}
```

> **Note:** Returns HTTP `202 Accepted` instead of `200` — signaling "your job is queued, not done yet."

