Standard factory functions to generate consistent responses:

```typescript
// ==========================================
// FILE: src/lib/api/api-response.ts
// ==========================================
import { NextResponse } from "next/server";
import { ApiErrorDetail, ApiErrorResponse, ApiSuccessResponse } from "@/types/api";

export function apiSuccess<T>(
  data: T,
  options: {
    status?: number;
    message?: string;
    meta?: Record<string, unknown>;
    headers?: HeadersInit;
  } = {},
): NextResponse<ApiSuccessResponse<T>> {
  const { status = 200, message, meta, headers } = options;

  const payload: ApiSuccessResponse<T> = {
    success: true,
    data,
    ...(message ? { message } : {}),
    ...(meta ? { meta } : {}),
  };

  return NextResponse.json(payload, { status, headers });
}

export function apiError(
  message: string,
  options: {
    status?: number;
    code?: string;
    details?: unknown;
    headers?: HeadersInit;
  } = {},
): NextResponse<ApiErrorResponse> {
  const {
    status = 500,
    code = "INTERNAL_SERVER_ERROR",
    details,
    headers,
  } = options;

  const errorDetail: ApiErrorDetail = {
    code,
    message,
    ...(details !== undefined ? { details } : {}),
  };

  return NextResponse.json(
    {
      success: false,
      error: errorDetail,
    },
    { status, headers },
  );
}
```

