### Step 4: Higher-Order Route Wrappers

> 📍 **Target File Path:** `src/lib/api/api-handler.ts`
> **Action:** Create new file

This eliminates manual `try/catch` blocks in every route and guarantees that bad requests or thrown errors will never crash the route.

```typescript
// ==========================================
// FILE: src/lib/api/api-handler.ts
// ==========================================
import { NextRequest, NextResponse } from "next/server";
import { formatErrorResponse } from "@/lib/errors/error-handler";
import { requireAuth } from "@/lib/auth-guard";
import { UnauthorizedError } from "@/lib/errors/app-error";
import type { Session } from "next-auth";

type RouteHandler<TContext = unknown> = (
  req: NextRequest,
  context: TContext,
) => Promise<NextResponse> | NextResponse;

type AuthenticatedRouteHandler<TContext = unknown> = (
  req: NextRequest,
  context: TContext & { session: Session },
) => Promise<NextResponse> | NextResponse;

/**
 * Global wrapper for any standard Next.js route handler
 */
export function withErrorHandler<TContext = unknown>(
  handler: RouteHandler<TContext>,
) {
  return async (req: NextRequest, context: TContext): Promise<NextResponse> => {
    try {
      return await handler(req, context);
    } catch (err) {
      return formatErrorResponse(err);
    }
  };
}

/**
 * Combines authentication guard + global error handling in one clean wrapper
 */
export function withAuthHandler<TContext = unknown>(
  handler: AuthenticatedRouteHandler<TContext>,
) {
  return withErrorHandler(async (req: NextRequest, context: TContext) => {
    const { session, error } = await requireAuth();
    if (error || !session?.user?.id) {
      throw new UnauthorizedError("You must be logged in to access this resource");
    }

    return await handler(req, { ...context, session });
  });
}
```

