import { NextRequest } from "next/server";
import { ProblemService } from "@/container";
import { withAuthHandler } from "@/lib/api/api-handler";
import { apiSuccess } from "@/lib/api/api-response";
import { NotFoundError } from "@/lib/errors/app-error";

export const GET = withAuthHandler(async (req: NextRequest) => {
  const { searchParams } = new URL(req.url);
  const problemId = searchParams.get("problemId");
  const visible = searchParams.get("visible") === "true";
  const slug = searchParams.get("slug");

  if (problemId) {
    const problem = visible
      ? await ProblemService.findByIdVisibleTests(problemId)
      : await ProblemService.findByIdAllTests(problemId);

    if (!problem) throw new NotFoundError(`Problem with ID '${problemId}' not found`);
    return apiSuccess(problem);
  }

  if (slug) {
    const problem = await ProblemService.findProblemBySlug(slug);
    if (!problem) throw new NotFoundError(`Problem with slug '${slug}' not found`);
    return apiSuccess(problem);
  }

  const problems = await ProblemService.findAllProblems();
  return apiSuccess(problems);
});
