### Step 6: Create Type-Safe Client Fetch Utility

> 📍 **Target File Path:** `src/lib/api/api-client.ts`
> **Action:** Create new file

Allows frontend components (`ProblemWorkspace`, `ProblemsList`, etc.) to call endpoints with full type inference and automated error extraction:

```typescript
// ==========================================
// FILE: src/lib/api/api-client.ts
// ==========================================
import { ApiResponse } from "@/types/api";

export class ApiClientError extends Error {
  public readonly code: string;
  public readonly status: number;
  public readonly details?: unknown;

  constructor(message: string, code: string, status: number, details?: unknown) {
    super(message);
    this.name = "ApiClientError";
    this.code = code;
    this.status = status;
    this.details = details;
  }
}

export async function fetchApi<T>(
  url: string,
  options?: RequestInit,
): Promise<T> {
  const res = await fetch(url, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...(options?.headers || {}),
    },
  });

  let payload: ApiResponse<T>;
  try {
    payload = await res.json();
  } catch {
    throw new ApiClientError(
      "Received invalid non-JSON response from server",
      "INVALID_RESPONSE",
      res.status,
    );
  }

  if (!payload.success) {
    throw new ApiClientError(
      payload.error.message,
      payload.error.code,
      res.status,
      payload.error.details,
    );
  }

  return payload.data;
}
```

