export default function SegmentError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    console.error("Unhandled UI error:", error);
  }, [error]);

  return (
    <div className="flex flex-col items-center justify-center min-h-[60vh] px-4 text-center select-none">
      <div className="w-14 h-14 rounded-2xl bg-[#ED4245]/20 border border-[#ED4245]/40 flex items-center justify-center text-[#ED4245] mb-4 shadow-lg">
        <AlertTriangle className="w-7 h-7" />
      </div>
      <h2 className="text-xl font-bold text-white mb-2 tracking-tight">
        Something went wrong
      </h2>
      <p className="text-sm text-[#949BA4] max-w-md mb-6 leading-relaxed">
        {error.message ||
          "An unexpected error occurred while loading this view."}
      </p>
      <button
        onClick={() => reset()}
        className="flex items-center gap-2 px-4 py-2 bg-[#5865F2] hover:bg-[#4752C4] text-white text-sm font-semibold rounded-lg shadow-md shadow-[#5865F2]/25 transition-all hover:scale-102 active:scale-98 cursor-pointer"
      >
        <RefreshCw className="w-4 h-4" />
        <span>Try Again</span>
      </button>
    </div>
  );
}

