export function ProblemWorkspace({ problem }: Props) {
  const { resolvedTheme } = useTheme();
  const [language, setLanguage] = useState<Language>("javascript");
  const [code, setCode] = useState(problem.starterJs);
  const [isRunning, setIsRunning] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitStatusText, setSubmitStatusText] = useState<string | null>(null);
  const [runResult, setRunResult] = useState<RunResponse | null>(null);
  const [submitResult, setSubmitResult] = useState<SubmitResponse | null>(null);
  const [activeTab, setActiveTab] = useState<"results" | null>(null);
  const [resultsHeight, setResultsHeight] = useState(240);
  const editorRef = useRef<MonacoType.editor.IStandaloneCodeEditor | null>(
    null,
  );
  const resizingResults = useRef(false);
  const resizeStartY = useRef(0);
  const resizeStartHeight = useRef(0);

  useEffect(() => {
    const onMove = (e: MouseEvent) => {
      if (!resizingResults.current) return;
      const delta = resizeStartY.current - e.clientY;
      setResultsHeight(
        Math.min(500, Math.max(100, resizeStartHeight.current + delta)),
      );
    };
    const onUp = () => {
      if (!resizingResults.current) return;
      resizingResults.current = false;
      document.body.style.userSelect = "";
      document.body.style.cursor = "";
    };
    document.addEventListener("mousemove", onMove);
    document.addEventListener("mouseup", onUp);
    return () => {
      document.removeEventListener("mousemove", onMove);
      document.removeEventListener("mouseup", onUp);
    };
  }, []);

  const handleLanguageChange = (lang: Language) => {
    setLanguage(lang);
    setCode(lang === "javascript" ? problem.starterJs : problem.starterPy);
    setRunResult(null);
    setSubmitResult(null);
    setActiveTab(null);
  };

  const handleResetCode = () => {
    setCode(language === "javascript" ? problem.starterJs : problem.starterPy);
  };

  const handlePrettify = () => {
    editorRef.current?.getAction("editor.action.formatDocument")?.run();
  };

  function handleKeyDown(event: React.KeyboardEvent) {
    if ((event.ctrlKey || event.metaKey) && event.key === "s") {
      event.preventDefault();
      handlePrettify();
    }
  }

  const handleRun = async () => {
    setIsRunning(true);
    setRunResult(null);
    setSubmitResult(null);
    try {
      const data = await fetchApi<RunResponse>("/api/run", {
        method: "POST",
        body: JSON.stringify({ problemId: problem.id, language, code }),
      });
      setRunResult(data);
      setActiveTab("results");
    } catch (err) {
      if (err instanceof ApiClientError) {
        console.error(`[${err.code}] ${err.message}`, err.details);
        alert(err.message);
      } else {
        alert("Run failed. Is Piston running? Check docker compose up.");
      }
    } finally {
      setIsRunning(false);
    }
  };

  const handleSubmit = async () => {
    setIsSubmitting(true);
    setSubmitStatusText("Queueing...");
    setRunResult(null);
    setSubmitResult(null);
    try {
      const submitData = await fetchApi<{
        submissionId: string;
        status: string;
      }>("/api/submit", {
        method: "POST",
        body: JSON.stringify({
          problemId: problem.id,
          language,
          code,
        }),
      });

      const submissionId = submitData.submissionId;
      setSubmitStatusText("Queued in worker...");

      // Poll submission status until completed or failed
      let attempts = 0;
      const maxAttempts = 60; // 60s timeout

      while (attempts < maxAttempts) {
        await new Promise((resolve) => setTimeout(resolve, 1000));
        attempts++;

        const statusRes = await fetchApi<{
          status: string;
          submissionId: string;
        }>(`/api/submit/status?id=${submissionId}`);

        const currentStatus = statusRes.status?.toUpperCase();

        if (currentStatus === "RUNNING") {
          setSubmitStatusText("Evaluating tests...");
        }

        if (currentStatus === "COMPLETED") {
          setSubmitStatusText("Fetching results...");
          const resultsRes = await fetchApi<{
            submission: {
              id: string;
              passed: boolean;
              message?: string;
              results?: TestResult[];
            };
          }>(`/api/submit/results?submission_id=${submissionId}`);

          const sub = resultsRes.submission;
          const results: TestResult[] = Array.isArray(sub?.results)
            ? sub.results
            : [];
          const passedCount = results.filter((r) => r.passed).length;
          const totalCount = results.length;

          setSubmitResult({
            passed:
              sub?.passed ?? (passedCount === totalCount && totalCount > 0),
            results,
            message:
              sub?.message ||
              (sub?.passed
                ? "All test cases passed! GG 🔥"
                : "Some test cases failed."),
            passedCount,
            totalCount,
            userLogs: [],
          });
          setActiveTab("results");
          break;
        }

        if (currentStatus === "FAILED") {
          throw new Error("Worker evaluation failed. Please check worker logs.");
        }
      }

      if (attempts >= maxAttempts) {
        throw new Error("Submission evaluation timed out after 60s.");
      }
    } catch (err) {
      if (err instanceof ApiClientError) {
        console.error(`[${err.code}] ${err.message}`, err.details);
        alert(err.message);
      } else if (err instanceof Error) {
        alert(err.message);
      } else {
        alert("Submit failed. Is Piston running? Check docker compose up.");
      }
    } finally {
      setIsSubmitting(false);
      setSubmitStatusText(null);
    }
  };

  const monacoLang = language === "javascript" ? "javascript" : "python";

  return (
    <div
      className="flex flex-col h-full min-h-0 bg-[#1E1F22] select-none"
      onKeyDown={handleKeyDown}
    >
      {/* Editor toolbar */}
      <div className="flex items-center justify-between px-4 py-2.5 bg-[#2B2D31] border-b border-[#1F2023] shrink-0">
        <div className="flex items-center gap-2">
          <div className="relative">
            <select
              value={language}
              onChange={(e) => handleLanguageChange(e.target.value as Language)}
              className="appearance-none bg-[#1E1F22] border border-[#35373C] text-white text-xs font-semibold rounded-lg pl-3 pr-8 py-1.5 focus:outline-none focus:border-[#5865F2] cursor-pointer transition-colors shadow-xs"
            >
              <option value="javascript">JavaScript (Node 18)</option>
              <option value="python">Python (3.10)</option>
            </select>
