export function ProblemsList({ problems }: { problems: ProblemSummary[] }) {
  const { data: Session } = useSession();
  const [solvedIds, setSolvedIds] = useState<Set<string>>(new Set());
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedDifficulty, setSelectedDifficulty] = useState<
    Difficulty | "ALL"
  >("ALL");
  const [filterSolved, setFilterSolved] = useState<
    "ALL" | "UNSOLVED" | "SOLVED"
  >("ALL");

  useEffect(() => {
    if (!Session?.user?.id) return;
    fetchApi<{ solvedIds: string[] }>("/api/user/solved")
      .then((data) => {
        if (Array.isArray(data.solvedIds)) {
          setSolvedIds(new Set(data.solvedIds));
        }
      })
      .catch(() => {});
  }, [Session?.user?.id]);

  const filteredProblems = useMemo(() => {
    return problems.filter((p) => {
      const matchesSearch =
        p.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.tags.some((t) => t.toLowerCase().includes(searchQuery.toLowerCase()));

      const matchesDiff =
        selectedDifficulty === "ALL" || p.difficulty === selectedDifficulty;

      const isSolved = solvedIds.has(p.id);
      const matchesSolved =
        filterSolved === "ALL" ||
        (filterSolved === "SOLVED" && isSolved) ||
        (filterSolved === "UNSOLVED" && !isSolved);

      return matchesSearch && matchesDiff && matchesSolved;
    });
  }, [problems, searchQuery, selectedDifficulty, filterSolved, solvedIds]);

  return (
    <div className="space-y-6">
      {/* Discord Toolbar: Search + Filter Bar */}
      <div className="bg-[#2B2D31] p-3.5 rounded-xl border border-[#1F2023] flex flex-col md:flex-row gap-3 items-stretch md:items-center justify-between">
        {/* Search Input */}
        <div className="relative flex-1 max-w-md">
          <Search
            size={16}
            className="absolute left-3 top-1/2 -translate-y-1/2 text-[#949BA4]"
          />
          <input
            type="text"
            placeholder="Search problems or tags (e.g. Array, Dynamic Programming)..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full bg-[#1E1F22] border border-[#35373C] rounded-lg pl-9 pr-3 py-2 text-sm text-[#DBDEE1] placeholder-[#949BA4] focus:outline-none focus:border-[#5865F2] transition-colors"
          />
        </div>

        {/* Filters */}
        <div className="flex items-center gap-2 flex-wrap">
          {/* Difficulty Dropdown */}
          <select
            value={selectedDifficulty}
            onChange={(e) =>
              setSelectedDifficulty(e.target.value as Difficulty | "ALL")
            }
            className="bg-[#1E1F22] border border-[#35373C] rounded-lg px-3 py-2 text-xs font-semibold text-[#DBDEE1] focus:outline-none focus:border-[#5865F2] cursor-pointer"
          >
            {DIFFICULTIES.map((d) => (
              <option key={d.value} value={d.value}>
                {d.label}
              </option>
            ))}
          </select>

          {/* Solved Status Filter */}
          <button
            onClick={() => {
              setFilterSolved((prev) =>
                prev === "ALL"
                  ? "UNSOLVED"
                  : prev === "UNSOLVED"
                    ? "SOLVED"
                    : "ALL",
              );
            }}
            className={`flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-semibold border transition-all ${
              filterSolved !== "ALL"
                ? "bg-[#5865F2]/20 border-[#5865F2] text-white"
                : "bg-[#1E1F22] border-[#35373C] text-[#949BA4] hover:text-white"
            }`}
          >
            <Filter size={13} />
            <span>
              {filterSolved === "ALL"
                ? "Status: All"
                : filterSolved === "UNSOLVED"
                  ? "Unsolved Only"
                  : "Solved Only"}
            </span>
          </button>
        </div>
      </div>

      {/* Problems Grid */}
      {filteredProblems.length > 0 ? (
        <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-3.5">
          {filteredProblems.map((problem, i) => (
            <ProblemCard
              key={problem.id}
              problem={problem}
              index={i}
              solved={solvedIds.has(problem.id)}
            />
          ))}
        </div>
      ) : (
        <div className="bg-[#2B2D31] rounded-xl border border-[#1F2023] p-12 text-center space-y-3">
          <div className="w-12 h-12 rounded-2xl bg-[#1E1F22] flex items-center justify-center text-[#949BA4] mx-auto">
            <Sparkles size={24} />
          </div>
          <h3 className="text-white font-bold text-base">No channels found</h3>
          <p className="text-[#949BA4] text-xs max-w-sm mx-auto">
            No problems matched your search or filters. Try resetting the
            filters above.
          </p>
        </div>
      )}
    </div>
  );
}

