export async function register() {
  if (process.env.NEXT_RUNTIME === "nodejs") {
    // Dynamic import — only loads Prisma in Node.js runtime, not Edge
    const { prisma } = await import("@/lib/prisma");

    // 1. Check DB Connection
    try {
      await prisma.$queryRaw`SELECT 1`;
      logger.info({ service: "postgres" }, "✅ DB connected successfully");
    } catch (err) {
      logger.error(
        { service: "postgres", err: err instanceof Error ? err.message : err },
        "❌ DB failed to connect:",
      );
    }

    //2. redis check
    try {
      const { redis } = await import("@/lib/redis");
      await redis.ping();
      logger.info({ service: "redis" }, " ✅  Redis connected Successfully");
    } catch (err) {
      logger.error(
        { service: redis, err: err instanceof Error ? err.message : err },
        "Redis Failed to connect",
      );
    }

    // 3. Check Piston Service
    const PISTON_URL = process.env.PISTON_URL || "http://localhost:2000";
    try {
      // Use standard fetch with an AbortController for timeout
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 3000);

      const res = await fetch(`${PISTON_URL}/api/v2/runtimes`, {
        method: "GET",
        signal: controller.signal,
      });

      clearTimeout(timeout);

      if (res.ok) {
        logger.info(
          { service: "piston", url: PISTON_URL },
          "✅ Piston service connected ",
        );
      } else {
        logger.error(
          { service: "piston", url: PISTON_URL, status: res.status },
          "❌ Piston service failed",
        );
      }
    } catch (err) {
      logger.error(
        {
          service: "piston",
          url: PISTON_URL,
          err: err instanceof Error ? err.message : err,
        },
        "Piston service connection failed",
      );
    }
  }
}

