type RouteHandler<TContext = unknown> = (
  req: NextRequest,
  context: TContext,
) => Promise<NextResponse> | NextResponse;

type AuthenticatedRouteHandler<TContext = unknown> = (
  req: NextRequest,
  context: TContext & { session: Session },
) => Promise<NextResponse> | NextResponse;

export function withErrorHandler<TContext = unknown>(
  handler: RouteHandler<TContext>,
) {
  return async (req: NextRequest, context: TContext): Promise<NextResponse> => {
    const startTime = Date.now();
    const method = req.method;
    const pathName = new URL(req.url).pathname;
    try {
      const response = await handler(req, context);
      const duration = (Date.now() - startTime) / 1000;
      const status = response.status;

      logger.info(
        { method, path: pathName, duration, status },
        "Request completed",
      );

      return response;
    } catch (err) {
      const errorRespose = formatErrorResponse(err);
      const duration = (Date.now() - startTime) / 1000;
      const status = errorRespose.status;
      logger.warn({ method, duration, status }, "Request Completed");
      return errorRespose;
    }
  };
}

async (req: NextRequest, context: TContext): Promise<NextResponse> => {
    const startTime = Date.now();
    const method = req.method;
    const pathName = new URL(req.url).pathname;
    try {
      const response = await handler(req, context);
      const duration = (Date.now() - startTime) / 1000;
      const status = response.status;

      logger.info(
        { method, path: pathName, duration, status },
        "Request completed",
      );

      return response;
    } catch (err) {
      const errorRespose = formatErrorResponse(err);
      const duration = (Date.now() - startTime) / 1000;
      const status = errorRespose.status;
      logger.warn({ method, duration, status }, "Request Completed");
      return errorRespose;
    }
  }

export function withAuthHandler<TContext = unknown>(
  handler: AuthenticatedRouteHandler<TContext>,
) {
  return withErrorHandler(async (req: NextRequest, context: TContext) => {
    const { session, error } = await requireAuth();
    if (error || !session?.user?.id) {
      throw new UnauthorizedError(
        "You must be logged in to access this resource",
      );
    }

    return await handler(req, { ...context, session });
  });
}

