export function formatErrorResponse(error: unknown) {
  // 1. Handled Operational Errors (AppError instances)
  if (error instanceof AppError) {
    return apiError(error.message, {
      status: error.statusCode,
      code: error.code,
      details: error.details,
    });
  }

  // 2. Zod Validation Errors
  if (error instanceof ZodError) {
    const formattedErrors = error.flatten();
    return apiError("Validation error", {
      status: 400,
      code: "VALIDATION_ERROR",
      details: {
        fieldErrors: formattedErrors.fieldErrors,
        formErrors: formattedErrors.formErrors,
      },
    });
  }

  // 3. Prisma Database Errors
  if (typeof error === "object" && error !== null && "code" in error) {
    const prismaError = error as {
      code: string;
      meta?: Record<string, unknown>;
    };

    // P2002: Unique constraint violation (e.g. unique email or slug)
    if (prismaError.code === "P2002") {
      const target =
        (prismaError.meta?.target as string[])?.join(", ") || "field";
      return apiError(`A record with this ${target} already exists.`, {
        status: 409,
        code: "CONFLICT",
      });
    }

    // P2025: Record not found
    if (prismaError.code === "P2025") {
      return apiError("Requested resource was not found.", {
        status: 404,
        code: "NOT_FOUND",
      });
    }
  }

  // 4. Unknown / Fatal Exceptions (Programming bugs, unhandled rejections, connection drops)
  console.error("🔥 [Unhandled Server Error]:", error);

  const isProduction = process.env.NODE_ENV === "production";
  const message = isProduction
    ? "An unexpected internal server error occurred."
    : error instanceof Error
      ? error.message
      : "An unexpected error occurred.";

  const details = isProduction
    ? undefined
    : error instanceof Error
      ? { stack: error.stack }
      : undefined;

  return apiError(message, {
    status: 500,
    code: "INTERNAL_SERVER_ERROR",
    details,
  });
}

