export class _ExecutionService {
  private readonly problemService: _ProblemService;

  constructor(problemService: _ProblemService) {
    this.problemService = problemService;
  }

  async runcode(
    problemId: string,
    language: "javascript" | "python",
    code: string,
  ) {
    //fetch testcases for the problem
    const problem = await this.problemService.findByIdVisibleTests(problemId);

    if (!problem) throw new Error("Problem not found");

    const fnName =
      language === "javascript" ? problem.fnNameJs : problem.fnNamePy;

    // format testcases into {input : {}, expected : {}}
    const testCases = problem.testCases.map((tc) => {
      return {
        input: tc.input as unknown[],
        expected: tc.expected,
      };
    });

    //call piston to execute code with testcases
    const { results } = await executeCode(language, code, fnName, testCases);
    const passesCount = results.filter((r) => r.passed).length;

    return { results, passesCount, totalCount: results.length };
  }
}

