export class _SubmissionService {
  private readonly submissionRepo: ISubmissionRepo; // Service -> Repo Call
  private readonly problemService: _ProblemService; // Service -> Service call

  constructor(
    submissionRepo: ISubmissionRepo,
    problemService: _ProblemService,
  ) {
    this.submissionRepo = submissionRepo;
    this.problemService = problemService;
  }

  /*

  steps in this function: 
  1. create a new submission record with pending status.
  2. create a job and store submission record id into the queue 
  3. return user the submisison id (to short poll upon)

  */
  async submitSolution(
    problemId: string,
    language: "javascript" | "python",
    code: string,
    userId: string,
  ) {
    const problem = await this.problemService.findByIdAllTests(problemId);
    if (!problem) throw new Error("Problem not found");

    const submission = await this.submissionRepo.createSubmission({
      userId,
      code,
      problemId,
      language,
      passed: false,
      passedAt: null,
      status: "PENDING",
    });

    const jobData: SubmissionJobData = {
      submissionId: submission.id,
    };

    await submissionQueue.add("execute", jobData, {
      jobId: submission.id,
    });

    return {
      submissionId: submission.id,
      status: "Pending",
    };
  }

  async getSubmissionStatus(submissionId: string, userId: string) {
    const submission = await this.submissionRepo.getSubmissionStatus(
      submissionId,
      userId,
    );
    if (!submission) {
      return null;
    }

    return {
      submissionId,
      userId,
      status: submission.status,
    };
  }

  async getSubmissionResults(submissionId: string, userId: string) {
    const submission = await this.submissionRepo.getSubmissionResults(
      submissionId,
      userId,
    );

    if (!submission) throw new Error("Submission not found");

    return submission;
  }
}

