const redis = new IORedis(process.env.REDIS_URL || "redis://localhost:6379", {
  maxRetriesPerRequest: null,
});

const worker = new Worker<SubmissionJobData>("submission", workerjob, {
  connection: redis,
  concurrency: 3, //process upto 3 submission in parallel
});

async function workerjob(job: Job<SubmissionJobData>) {
  const { submissionId } = job.data;

  logger.info(
    { submissionId, jobId: job.id },
    "Worker Started processing submission",
  );

  blockMainThread(10000);

  // update problem status to running
  const submisison = await prisma.submission.update({
    where: { id: submissionId },
    data: { status: "RUNNING" },
    select: { code: true, language: true, problemId: true },
  });

  const { code, language, problemId } = submisison;

  //fetch problem with testcases
  const problem = await prisma.problem.findUnique({
    where: { id: problemId },
    include: { testCases: true },
  });

  if (!problem) throw new Error(`Problem ${problemId} not found`);

  //prepare fnName and testcases object
  const fnName =
    language === "javascript" ? problem.fnNameJs : problem.fnNamePy;

  const testCases = problem.testCases.map((tc) => {
    return {
      input: tc.input as unknown[],
      expected: tc.expected as unknown[],
    };
  });

  const { results } = await executeCode(
    language as "javascript" | "python",
    code,
    fnName,
    testCases,
  );

  const passedCount = results.filter((r) => r.passed).length;
  const allPassed = passedCount === testCases.length;
  const message = randomMessage(allPassed);

  blockMainThread(10000);

  await prisma.submission.update({
    where: { id: submissionId },
    data: {
      status: "COMPLETED",
      passed: allPassed,
      results: results as any,
      passedAt: allPassed ? new Date() : null,
      message,
    },
  });

  logger.info(
    {
      submissionId,
      jobId: job.id,
      passes: allPassed,
      totalCount: testCases.length,
    },
    `Submission ${allPassed ? "Passed" : "Failed"}`,
  );
  return { passed: allPassed, passedCount, totalCount: testCases.length };
}

